170	    nullValues?: Record<string, string | null>;
171	}
172	/**
173	 * Main chart visualization config
174	 */
175	export interface YagrChartOptions {
176	    /** Common series options, could be overriden by series.<option> field */
177	    series?: SeriesOptions;
178	    size?: {
179	        /** width (by default: 100% of root) */
180	        width?: number;
181	        /** height (by default: 100% of root) */
182	        height?: number;
183	        /** padding in css px [top, right, bottom, left] (by default: utils.chart.getPaddingByAxes) */
184	        padding?: [number, number, number, number];
185	        /** Should chart redraw on container resize (default: true) */
186	        adaptive?: boolean;
187	        /** Debounce timer for ResizeObserver to trigger: (default 100 ms) */
188	        resizeDebounceMs?: number;
189	    };
190	    select?: {
