```ts
export interface CpuSeries {
  timeline: number[]; // ms timestamps
  values: number[];   // cpu %
}

export const WINDOW_SECONDS = 24 * 60 * 60; // 24h at 1s resolution = 86 400 points
export const TICK_MS = 1000;

const clamp = (v: number, min: number, max: number) => Math.min(max, Math.max(min, v));

// random walk with mean reversion + daily cycle
export function nextCpuValue(prev: number, tMs: number): number {
  const hours = new Date(tMs).getHours() + new Date(tMs).getMinutes() / 60;
  const daily = 35 + 25 * Math.sin(((hours - 9) / 24) * Math.PI * 2); // day peak ~15:00
  const reverted = prev + (daily - prev) * 0.002;
  const noise = (Math.random() - 0.5) * 2.2;
  const spike = Math.random() < 0.002 ? Math.random() * 25 : 0;
  return clamp(reverted + noise + spike, 0.5, 99.5);
}

export function createInitialSeries(nowMs: number): CpuSeries {
  const timeline = new Array<number>(WINDOW_SECONDS);
  const values = new Array<number>(WINDOW_SECONDS);
  let v = 30 + Math.random() * 20;
  const start = nowMs - (WINDOW_SECONDS - 1) * TICK_MS;
  for (let i = 0; i < WINDOW_SECONDS; i++) {
    const t = start + i * TICK_MS;
    v = nextCpuValue(v, t);
    timeline[i] = t;
    values[i] = Math.round(v * 10) / 10;
  }
  return {timeline, values};
}
```

